def _llama_non_streaming_generation_timeout() -> httpx.Timeout:
    return httpx.Timeout(_DEFAULT_FIRST_TOKEN_TIMEOUT_S)


def _llama_streaming_generation_timeout() -> httpx.Timeout:
    return httpx.Timeout(_DEFAULT_FIRST_TOKEN_TIMEOUT_S)


def _set_stream_response_read_timeout(
    response: httpx.Response, read_timeout_s: Optional[float] = _DEFAULT_STREAM_STALL_TIMEOUT_S
) -> None:
    # ``read_timeout_s = None`` clears httpx's read timeout (wait indefinitely),
    # used when the stall guard is disabled so a stale first-token deadline
    # can't keep timing out post-first-chunk gaps.
    try:
        timeout_ext = response.request.extensions.get("timeout")
        if isinstance(timeout_ext, dict):
            timeout_ext["read"] = read_timeout_s
    except Exception:
        pass


_STREAM_DISCONNECT_POLL_TIMEOUT_S = 0.25
_OPENAI_PASSTHROUGH_PREHEADER_STATUS_WINDOW_S = 0.1
_OPENAI_PASSTHROUGH_PENDING_RESPONSE_KEEPALIVE_S = 5.0
_OPENAI_PASSTHROUGH_SSE_KEEPALIVE = ": keep-alive\n\n"
# Lets a client tell "queued" from "backend silent"; SSE comments, so readers ignore both.
_OPENAI_ADMISSION_SSE_WAIT = ": admission-wait\n\n"
# Paired with the above: the slot is ours, so a suspended client clock starts now.
_OPENAI_ADMISSION_SSE_DONE = ": admission-done\n\n"
_OPENAI_LLAMA_ADMISSION_POLL_S = 0.25
# Cap on waiting for a cancelled teardown task. Request.is_disconnected() can swallow
# cancel() (#7617), so teardown abandons the task rather than hold the response, and
# the process-wide slot, open forever.
_TEARDOWN_TASK_STOP_TIMEOUT_S = 5.0
# Idle window before a local tool-loop stream emits an SSE keepalive comment
# (e.g. prompt prefill between tool iterations). A second layer atop the
# tool_stream_exec heartbeats, keeping proxies (Cloudflare drops idle at ~100s).
_LOCAL_TOOL_STREAM_STALL_KEEPALIVE_S = 15.0


def _openai_llama_admission_capacity(request: Optional[Request], llama_backend = None) -> int:
    """Serving slots available for one local llama-server backend.

    The loaded backend is the source of truth because it may have reduced
    ``--parallel`` at load time to keep the model on GPU. The app state is a
    launch-intent fallback for tests and for the short window before a backend
    reports its committed runtime slots.
    """
    slots = _positive_int_or_none(getattr(llama_backend, "effective_parallel_slots", None))
    if slots is not None:
        return slots
    try:
        slots = getattr(request.app.state, "llama_parallel_slots", None)
    except Exception:
        slots = None
    return _positive_int_or_none(slots) or 1


def _openai_llama_admission_budget(llama_backend) -> Optional[int]:
    """KV tokens the running llama-server actually allocated, or None if unknown.

    ``_kv_cache_context_total`` is the aggregate, and is preferred where the backend
    has it. ``context_length`` is NOT that once the server has been read back:
    ``_reconcile_effective_ctx_with_server`` adopts the PER-SLOT ``n_ctx`` from
    ``default_generation_settings`` into it, and computes the total alongside as
    ``n_ctx * slots`` (slots being 1 only under ``--kv-unified``). Unsloth appends
    that flag only when ``n_parallel > 1`` and the binary supports it, so a build
    without it, or a user ``--no-kv-unified``, gives N private caches while
    ``context_length`` names one of them: an N-fold under-budget that collapses
    concurrency to a single generation.

    Falls back to ``context_length`` when the total is unset (nothing has been read
    back yet, in which case the two agree), and None when the backend cannot say,
    which keeps slot-only admission rather than inventing a budget.
    """
    total = _positive_int_or_none(getattr(llama_backend, "_kv_cache_context_total", None))
    return total or _positive_int_or_none(getattr(llama_backend, "context_length", None))


def _openai_llama_admission_can_yield(llama_backend) -> bool:
    """Whether a round between generations may hand its commitment back.

    Only where llama-server actually clears an idle slot's KV. Under ``--kv-unified``
    without ``--cache-idle-slots`` a finished round's cells stay resident, so yielding
    would promise the same capacity twice. Studio launches exactly that way on Windows
    under full GPU offload (``--cache-ram 0``, #5692); there re-costing declines instead
    of waiting. A backend that cannot say (no load yet, or a stub) reads as False.
    """
    return bool(getattr(llama_backend, "idle_slot_clearing_active", False))


def _openai_llama_admission_extra_prompt_tokens(payload) -> int:
    """Prompt the request carries OUTSIDE ``messages``, in tokens.

    OpenAI tool definitions are rendered into the llama-server prompt, and Anthropic
    keeps ``system`` and ``tools`` separate until they are translated. Sizing only the
    message list let two requests with small messages but large system instructions or
    JSON tool schemas both be admitted on a severe undercount.

    Serialised and charged at the dense rate, since a JSON schema is punctuation-heavy
    and the four-chars-per-token rule flatters it.
    """
    extra = 0
    for attribute in ("system", "tools", "tool_choice", "instructions"):
        value = getattr(payload, attribute, None)
        if value is None or isinstance(value, (bool, int, float)):
            continue
        try:
            text = value if isinstance(value, str) else json.dumps(value, default = str)
        except Exception:
            continue
        if text:
            extra += estimate_messages_tokens_dense([{"role": "system", "content": text}])
    return extra


# An upper bound per image, not an estimate: under-reserving hands out a slot the cache
# cannot back, which is the overcommit #9392 exists to stop.
#
# 4096 is llama.cpp's default Qwen-VL embedding cap (the projector resizes to its own
# pixel limits, so transport size never enters into it), but mtmd wraps the embeddings
# in delimiters. Measured on llama-server b10639: 4098 for a 2048x2048 image on
# Qwen3-VL-4B, 258 on Gemma 3 4B. The wrapper allowance is far above the two measured
# so longer delimiters still fit. Only the DEFAULT, though: a load may raise the cap
# (`_openai_llama_admission_image_tokens`), and a projector whose embeddings exceed it
# on their own (tiling or multi-crop families) still wants an allowance read off the
# loaded mmproj rather than a bigger number here.
_OPENAI_LLAMA_ADMISSION_IMAGE_EMBEDDING_CAP = 4096
_OPENAI_LLAMA_ADMISSION_IMAGE_WRAPPER_TOKENS = 128
_OPENAI_LLAMA_ADMISSION_IMAGE_TOKENS = (
    _OPENAI_LLAMA_ADMISSION_IMAGE_EMBEDDING_CAP + _OPENAI_LLAMA_ADMISSION_IMAGE_WRAPPER_TOKENS
)

# An ESTIMATE where the rest of the sizing is a bound: a run that generates more is
# undercharged until something re-costs it, which a tool loop does every round boundary and
# a plain chat cannot yet, so on a full cache a long uncapped generation can still overrun.
_OPENAI_LLAMA_ADMISSION_UNSTATED_OUTPUT_TOKENS = (
    _positive_int_or_none(os.environ.get("UNSLOTH_LLAMA_ADMISSION_UNSTATED_OUTPUT_TOKENS")) or 1024
)


def _openai_llama_admission_context_window(llama_backend) -> Optional[int]:
    """One slot, which under ``--no-kv-unified`` is 1/N of the aggregate budget."""
    return _positive_int_or_none(getattr(llama_backend, "context_length", None))


def _openai_llama_admission_output_allowance(
    cap: Optional[int],
    *,
    budget: int,
    prompt_tokens: int,
    context_window: Optional[int] = None,
    share: Optional[int] = None,
) -> int:
    """KV to reserve for what a request may still generate.

    A cap at or above the window is not a cap: `_build_passthrough_payload` sends
    max_tokens = backend_ctx and "Max" sends the context length, so both mean unstated, and
    charging the window for either serialises the queue. Measured against the per-request
    window, since the budget is N times larger under --no-kv-unified.

    Invariant when a ``share`` is known: an unstated request costs at most its fair share of
    the cache, so ``capacity`` of them always fit. A flat allowance breaks that on a small
    cache, where 1024 is most of a share on its own (4096 over four slots admitted three).
    A prompt already past its share keeps the flat allowance, since it does not fit either
    way and a zero allowance would only hide that it will still generate.
    """
    window = context_window or budget
    if cap is not None and cap < window:
        return cap
    # Clamped to the WINDOW: a request cannot occupy more KV than its own slot holds.
    allowance = min(_OPENAI_LLAMA_ADMISSION_UNSTATED_OUTPUT_TOKENS, max(0, window - prompt_tokens))
    if share is not None and share > prompt_tokens:
        allowance = min(allowance, share - prompt_tokens)
    return allowance


def _extra_args_image_max_tokens(extra_args) -> Optional[int]:
    """The ``--image-max-tokens N`` a load passed through, or None. Last wins.

    Both spellings, since llama-server accepts ``--flag N`` and ``--flag=N``.
    """
    args = [str(arg) for arg in (extra_args or ())]
    found = None
    for index, raw in enumerate(args):
        if raw.startswith("--image-max-tokens="):
            value = raw.partition("=")[2]
        elif raw == "--image-max-tokens" and index + 1 < len(args):
            value = args[index + 1]
        else:
            continue
        parsed = _positive_int_or_none(value)
        if parsed is not None:
            found = parsed
    return found


# Embeddings one image may become, per projector family, from llama.cpp's own
# `set_limit_image_tokens` calls in tools/mtmd/clip.cpp; the keys are the
# `clip.projector_type` strings in clip-impl.h, which is what the mmproj GGUF carries.
# There is no universal default -- `--image-max-tokens` documents itself as "read from
# model" -- and the spread is three orders of magnitude, so assuming any one number
# under-reserves somebody. A family absent here falls back to the default ceiling
# below, which is the pre-existing behaviour rather than a new guess.
_MMPROJ_IMAGE_TOKEN_MAX = {
    "qwen2vl_merger": 4096,
    "qwen2.5vl_merger": 4096,
    "qwen3vl_merger": 4096,
    "glm4v": 4096,
    "kimik25": 4096,
    "muse-glimmer": 4096,
    "youtuvl": 62500,
    "hunyuanvl": 16384,
    "pixtral": 1024,
    "lightonocr": 1024,
    "kimivl": 1024,
    "minimax_m3": 576,
    "gemma4v": 280,
    "gemma4uv": 280,
    "lfm2": 256,
}


def _openai_llama_admission_image_tokens(llama_backend) -> int:
    """Per-image KV allowance for the backend that is actually running.

    Two things move the ceiling off the default. The loaded projector sets its own:
    measured on b10639, a max-resolution image is 4098 KV positions on Qwen3-VL-4B and
    258 on Gemma 3 4B, and clip.cpp's own table runs from 256 (lfm2) to 62500 (youtuvl).
    And ``--image-max-tokens`` is not an Unsloth-managed flag, so ``llama_extra_args``
    forwards one verbatim: with ``--image-max-tokens 8192`` that same Qwen3-VL image
    costs 8102.

    Takes the LARGER of the two rather than trusting the flag, because llama-server
    applies it only to dynamic-resolution projectors -- a low cap against a fixed
    resolution one is ignored, and believing it would reserve less than the image costs.
    Over-reserving is the safe direction; under-reserving hands out a slot the cache
    cannot back.
    """
    projector = getattr(llama_backend, "_mmproj_projector_type", None)
    known = _MMPROJ_IMAGE_TOKEN_MAX.get(str(projector).strip().lower()) if projector else None
    cap = max(
        known or _OPENAI_LLAMA_ADMISSION_IMAGE_EMBEDDING_CAP,
        _extra_args_image_max_tokens(getattr(llama_backend, "_extra_args", None)) or 0,
    )
    return cap + _OPENAI_LLAMA_ADMISSION_IMAGE_WRAPPER_TOKENS


def _openai_llama_admission_messages_for_estimate(messages) -> tuple[list[dict], int]:
    """Remove image bytes before estimating the textual part of a prompt.

    mtmd turns an image into model-specific embedding tokens, so its base64 transport
    is neither prompt text nor a proxy for that count. Keep each image part's shape for
    the JSON estimate and return the count, so the caller can add a bounded allowance.
    """
    estimate_messages = []
    image_parts = 0
    for message in messages:
        # exclude_none like every other dump here, including the generation paths this
        # predicts: the five unset optionals on ChatMessage otherwise serialise as
        # `"name": null` and get priced as prompt text (34 tokens for a two-key message
        # against 8), reserving KV for punctuation that is never sent.
        message_dict = (
            message if isinstance(message, dict) else message.model_dump(exclude_none = True)
        )
        estimate_message = dict(message_dict)
        content = message_dict.get("content")
        if isinstance(content, list):
            estimate_content = []
            for part in content:
                if not isinstance(part, dict) or part.get("type") != "image_url":
                    estimate_content.append(part)
                    continue

                image_parts += 1
                image_url = part.get("image_url")
                compact_image_url = {"url": "[image]"}
                if isinstance(image_url, dict) and image_url.get("detail") is not None:
                    compact_image_url["detail"] = image_url["detail"]
                estimate_content.append(
                    {
                        "type": "image_url",
                        "image_url": compact_image_url,
                    }
                )
            estimate_message["content"] = estimate_content
        estimate_messages.append(estimate_message)
    return estimate_messages, image_parts


def _openai_llama_admission_media_tokens(
    payload,
    *,
    message_image_parts: int = 0,
    image_tokens: int = _OPENAI_LLAMA_ADMISSION_IMAGE_TOKENS,
) -> int:
    """Estimate media KV usage without charging transport bytes as prompt tokens.

    Charges the legacy top-level image on exactly the condition both builders splice it
    on, ``_legacy_image_is_distinct``: Studio echoes one image into both spellings, so
    charging that twice reserves it twice, while a legacy image the messages do not
    already carry is a second image really sent. The allowance is per-image rather than
    per-byte because the real mtmd count follows the loaded projector, not base64 length.

    Audio and video keep the old top-level accounting until they have a model-specific
    estimate; this is scoped to the image path that regressed vision concurrency.
    """
    extra = 0
    extra += max(0, message_image_parts) * image_tokens
    if _legacy_image_is_distinct(payload):
        extra += image_tokens
    for attribute in ("audio_base64", "video_base64"):
        value = getattr(payload, attribute, None)
        if isinstance(value, str) and value:
            extra += max(1, len(value) // 4)
    return extra


def _openai_llama_admission_injected_tool_tokens(injected_tools) -> int:
    """The tool catalogue Unsloth adds itself, in tokens.

    ``payload.tools`` is what the CLIENT sent, and for Unsloth's own tool loop that is
    usually nothing: Web Search and the rest resolve server-side and render into the
    prompt after admission has priced the request. Measured on Qwen3.5-4B-MTP-GGUF, the
    same user turn is 1716 prompt tokens with tools off and 2969 with them on, so the
    catalogue is around 1250 tokens the message list cannot see.

    Leaving it out is not a rounding error: at ``-c 4096`` four requests priced at an
    equal share were all admitted and llama.cpp answered every one with ``Context size
    has been exceeded``.
    """
    if not injected_tools:
        return 0
    try:
        text = json.dumps(injected_tools, default = str)
    except Exception:
        return 0
    if not text:
        return 0
    return estimate_messages_tokens_dense([{"role": "system", "content": text}])


def _openai_llama_admission_tokens(
    payload,
    *,
    budget: Optional[int],
    capacity: int,
    tool_loop: bool = False,
    image_tokens: int = _OPENAI_LLAMA_ADMISSION_IMAGE_TOKENS,
    injected_tools = None,
    context_window: Optional[int] = None,
) -> Optional[int]:
    """KV a request will occupy: what is sent, plus what it may generate.

    Uses the dense estimator, not the plain one. Undercounting is the failure this
    accounting exists to prevent, and four-chars-per-token undercounts CJK by about
    2x, which would hand out a slot the cache cannot back.

    A shape with no messages (``/completions`` takes a prompt string) falls back to
    an equal share of the cache: charging it the whole budget would serialise that
    route, and charging it nothing would restore the overcommit.
    """
    if not budget:
        return None
    messages = getattr(payload, "messages", None)
    if isinstance(messages, list) and messages:
        try:
            estimate_messages, message_image_parts = _openai_llama_admission_messages_for_estimate(
                messages
            )
            prompt_tokens = estimate_messages_tokens_dense(estimate_messages)
            prompt_tokens += _openai_llama_admission_extra_prompt_tokens(payload)
            prompt_tokens += _openai_llama_admission_injected_tool_tokens(injected_tools)
            prompt_tokens += _openai_llama_admission_media_tokens(
                payload,
                message_image_parts = message_image_parts,
                image_tokens = image_tokens,
            )
        except Exception:
            prompt_tokens = None
    else:
        prompt_tokens = None
    if prompt_tokens is None:
        return max(1, budget // max(1, capacity))
    # The same helper generation honours, not the raw field. A request that sets only
    # the supported max_completion_tokens and leaves the deprecated max_tokens unset
    # would otherwise reserve its prompt and none of its output allowance.
    cap = _positive_int_or_none(
        _effective_openai_max_tokens_from_values(
            getattr(payload, "max_tokens", None),
            getattr(payload, "max_completion_tokens", None),
        )
    )
    # Reserving the rest of the budget for either made concurrency 1 for the default chat.
    output_tokens = _openai_llama_admission_output_allowance(
        cap,
        budget = budget,
        prompt_tokens = prompt_tokens,
        context_window = context_window,
        share = max(1, budget // max(1, capacity)),
    )
    # A tool loop opens at its own estimate with an equal share as the floor, and re-costs
    # as it grows (generate_chat_completion_with_tools on_conversation_grew ->
    # lease.recost_waiting). The floor keeps re-costing rare: under its share a run never
    # calls the queue at all.
    #
    # #9392 reserved the WHOLE cache here instead, closing the same growth without a
    # callback "at the price of serialising concurrent tool requests". That price is not
    # payable: any lit pill sets enable_tools, so every tool chat ran alone. Measured on a
    # 262144 cache, four tool chats went one at a time at 0.1/2.8/4.6/8.8s to first token;
    # with this they start together. It also scaled the wrong way: #9392's own failure was
    # a 2048-token cache where 565 + 1485 overflowed, so reserving all of that cost a
    # request that could not have run anyway, while reserving all of 262144 costs three
    # that comfortably could.
    #
    # Keyed on the resolved execution path, NOT on payload.tools. The loop opens on
    # `enable_tools`, `mcp_enabled`, the CLI --enable-tools policy or a checkpoint
    # repair, none of which need a client `tools` array, so keying on the array
    # undercharged Unsloth's own tool traffic; and a passthrough or /responses request
    # that merely forwards `tools` to llama-server runs ONE generation per HTTP call.
    if tool_loop:
        # Exactly what the same request without tools is charged, floored at an equal
        # share. A tool loop is a special case at ROUND time, not at admission time.
        #
        # Not clamped to the share: charging less than prompt + output reopens what #9392
        # closed, since a first round may generate its whole output allowance before any
        # re-cost runs. The floor only helps a SMALL request, the one that would otherwise
        # re-cost on its very first round.
        share = max(1, budget // max(1, capacity))
        return max(1, min(budget, max(share, prompt_tokens + output_tokens)))
    # Clamped to the budget so an oversized request stays schedulable: the queue
    # admits it alone rather than stranding it, and llama-server refuses it with a
    # message naming both counts.
    return max(1, min(budget, prompt_tokens + output_tokens))


def _openai_llama_admission_reserve(
    *,
    request: Optional[Request],
    llama_backend,
    payload = None,
    tool_loop: bool = False,
    injected_tools = None,
) -> tuple[LlamaAdmissionReservation, LlamaAdmissionConfig]:
    config = llama_admission_config_from_env()
    capacity = _openai_llama_admission_capacity(request, llama_backend)
    key = str(getattr(llama_backend, "base_url", "llama-server"))
    budget = _openai_llama_admission_budget(llama_backend)
    reservation = get_llama_admission_queue(key).reserve(
        capacity = capacity,
        config = config,
        budget = budget,
        tokens = _openai_llama_admission_tokens(
            payload,
            budget = budget,
            capacity = capacity,
            tool_loop = tool_loop,
            image_tokens = _openai_llama_admission_image_tokens(llama_backend),
            injected_tools = injected_tools,
            context_window = _openai_llama_admission_context_window(llama_backend),
        )
        if payload is not None
        else None,
    )
    return reservation, config


def _openai_llama_admission_recost(
    reservation,
    conversation,
    *,
    request: Optional[Request],
    llama_backend,
    payload = None,
    output_tokens: Optional[int] = None,
    cancel_event = None,
    injected_tools = None,
) -> None:
    """Charge a tool loop for what its conversation now is, not what it opened as.

    #9392 avoided this by reserving the whole cache for any tool run, serialising every
    tool chat. Called at the top of each round, this keeps the commitment honest as the
    conversation grows, so the opening reservation can be an ordinary estimate and four
    tool chats can decode at once.

    Growth that does not fit WAITS here rather than proceeding uncharged: four loops that
    open at a share each and grow past it together draw one ``Context size has been
    exceeded`` that kills every decoding slot. ``recost_waiting`` yields the old
    commitment first, so a waiting round is not holding the room it waits for.

    Safe to wait here because it is between rounds and the slot is idle at llama-server.
    Idle is not reclaimed, though, so the yield is gated on
    ``_openai_llama_admission_can_yield``; where it is False this declines instead.
    """
    if reservation is None:
        return
    try:
        lease = reservation.lease_nowait()
        if lease is None:
            return
        budget = _openai_llama_admission_budget(llama_backend)
        if not budget:
            return
        capacity = _openai_llama_admission_capacity(request, llama_backend)
        # Every term the OPENING reservation charges, charged again here. Counting fewer
        # things than the reservation it replaces would SHRINK a correctly sized lease --
        # and since the callback fires at the top of round zero, before any growth, it
        # would hand back room llama-server is already using.
        estimate_messages, message_image_parts = _openai_llama_admission_messages_for_estimate(
            conversation
        )
        prompt_tokens = estimate_messages_tokens_dense(estimate_messages)
        # Re-sent every round, so it belongs in every re-costing, not just the opening one.
        prompt_tokens += _openai_llama_admission_injected_tool_tokens(injected_tools)
        # Anthropic keeps `system` and `tools` out of the message list entirely, so for
        # that route this is most of the prompt.
        prompt_tokens += _openai_llama_admission_extra_prompt_tokens(payload)
        # mtmd embeddings, KV the message text cannot show: image parts compact to
        # "[image]" for the text estimate, so their real cost comes from the compaction
        # count. A screenshot tool adds more of them, so this grows with the rounds.
        prompt_tokens += _openai_llama_admission_media_tokens(
            payload,
            message_image_parts = message_image_parts,
            image_tokens = _openai_llama_admission_image_tokens(llama_backend),
        )
        # Reading "Max" literally here would put the run back on the whole cache at its
        # first round boundary.
        share = max(1, budget // max(1, capacity))
        output_tokens = _openai_llama_admission_output_allowance(
            output_tokens,
            budget = budget,
            prompt_tokens = prompt_tokens,
            context_window = _openai_llama_admission_context_window(llama_backend),
            share = share,
        )
        want = max(1, min(budget, max(share, prompt_tokens + max(0, output_tokens))))
        lease.recost_waiting(
            want,
            cancel_event = cancel_event,
            allow_yield = _openai_llama_admission_can_yield(llama_backend),
        )
    except Exception:  # pragma: no cover - accounting must not break a live run
        logger.debug("llama admission recost failed", exc_info = True)


def _openai_admission_request_path(request: Optional[Request]) -> Optional[str]:
    try:
        return str(request.url.path) if request is not None else None
    except Exception:
        return None


def _llama_admission_log(
    event: str,
    reservation: Optional[LlamaAdmissionReservation] = None,
    *,
    snapshot = None,
    request: Optional[Request],
    mode: str,
    wait_started_at: Optional[float] = None,
    completion_id: Optional[str] = None,
    level: str = "debug",
) -> None:
    if snapshot is None and reservation is not None:
        snapshot = reservation.snapshot_now()
    wait_ms = None
    if wait_started_at is not None:
        wait_ms = int(max(0.0, time.monotonic() - wait_started_at) * 1000)
    log = getattr(logger, level, logger.debug)
    log(
        "llama admission %s: mode=%s path=%s completion_id=%s "
        "pool=%s/%s free=%s queued=%s wait_ms=%s",
        event,
        mode,
        _openai_admission_request_path(request),
        completion_id,
        getattr(snapshot, "active", None),
        getattr(snapshot, "capacity", None),
        getattr(snapshot, "free", None),
        getattr(snapshot, "queued", None),
        wait_ms,
    )


def _openai_admission_error_body(exc: Exception, *, status_code: int) -> dict:
    snapshot = getattr(exc, "snapshot", None)
    message = str(exc)
    if snapshot is not None:
        message = (
            f"{message} "
            f"(active={snapshot.active}, queued={snapshot.queued}, capacity={snapshot.capacity})"
        )
    return openai_error_body(message, status = status_code)


def _openai_admission_http_exception(exc: Exception, *, status_code: int) -> HTTPException:
    return HTTPException(
        status_code = status_code,
        detail = _openai_admission_error_body(exc, status_code = status_code),
    )


def _anthropic_admission_http_exception(exc: Exception, *, status_code: int) -> HTTPException:
    """Anthropic-shaped error for an admission reject/timeout/cancel (429/503/499)."""
    snapshot = getattr(exc, "snapshot", None)
    message = str(exc)
    if snapshot is not None:
        message = (
            f"{message} "
            f"(active={snapshot.active}, queued={snapshot.queued}, capacity={snapshot.capacity})"
        )
    # Types come from ANTHROPIC_TYPE_BY_STATUS (429 -> rate_limit_error, which is
    # what Anthropic SDKs back off on); overloaded_error is reserved for 529.
    return HTTPException(
        status_code = status_code,
        detail = anthropic_error_body(message, status = status_code),
    )


def _openai_admission_timeout_error(
    reservation: LlamaAdmissionReservation,
) -> LlamaAdmissionTimeout:
    return LlamaAdmissionTimeout(
        "Timed out waiting for an available local llama-server generation slot",
        snapshot = reservation.snapshot_now(),
    )


def _openai_admission_cancelled_error(
    reservation: LlamaAdmissionReservation,
) -> LlamaAdmissionCancelled:
    return LlamaAdmissionCancelled(
        "Client disconnected before an upstream llama-server generation slot was available",
        snapshot = reservation.snapshot_now(),
    )


async def _raise_if_openai_admission_cancelled(
    reservation: LlamaAdmissionReservation, *, request: Optional[Request], cancel_event
) -> None:
    # Cancelled before leasing an upstream, so the model was never used. A streaming caller
    # has flushed the 200 headers and its `except LlamaAdmissionCancelled` just returns, so
    # flag failed: the middleware must not treat that empty 200 as a successful generation and
    # claim a preview-owned slot. Harmless for non-streaming callers (they surface a non-2xx).
    from core.inference.llama_keepwarm import mark_current_response_failed
    if reservation.is_cancelled:
        mark_current_response_failed()
        raise _openai_admission_cancelled_error(reservation)
    if await _preheader_cancelled(cancel_event, request):
        reservation.cancel()
        mark_current_response_failed()
        raise _openai_admission_cancelled_error(reservation)


async def _wait_for_openai_admission_non_streaming(
    reservation: LlamaAdmissionReservation,
    config: LlamaAdmissionConfig,
    *,
    request: Optional[Request],
    cancel_event,
) -> LlamaAdmissionLease:
    lease = reservation.lease_nowait()
    if lease is not None:
        try:
            await _raise_if_openai_admission_cancelled(
                reservation,
                request = request,
                cancel_event = cancel_event,
            )
        except asyncio.CancelledError:
            lease.release()
            raise
        except LlamaAdmissionCancelled:
            lease.release()
            raise
        return lease
    await _raise_if_openai_admission_cancelled(
        reservation,
        request = request,
        cancel_event = cancel_event,
    )
    deadline = None if config.queue_timeout_s is None else time.monotonic() + config.queue_timeout_s
    try:
        while True:
            await _raise_if_openai_admission_cancelled(
                reservation,
                request = request,
                cancel_event = cancel_event,
            )
            lease = reservation.lease_nowait()
            if lease is not None:
                try:
                    await _raise_if_openai_admission_cancelled(
                        reservation,
                        request = request,
                        cancel_event = cancel_event,
                    )
                except asyncio.CancelledError:
                    lease.release()
                    raise
                except LlamaAdmissionCancelled:
                    lease.release()
                    raise
                return lease
            wait_s = _OPENAI_LLAMA_ADMISSION_POLL_S
            if deadline is not None:
                remaining_s = deadline - time.monotonic()
                if remaining_s <= 0:
                    reservation.cancel()
                    raise _openai_admission_timeout_error(reservation)
                wait_s = min(wait_s, max(remaining_s, 0.001))
            try:
                lease = await reservation.wait(wait_s)
            except asyncio.TimeoutError:
                continue
            if lease is not None:
                return lease
            await _raise_if_openai_admission_cancelled(
                reservation,
                request = request,
                cancel_event = cancel_event,
            )
    except asyncio.CancelledError:
        reservation.cancel()
        raise


async def _openai_admission_wait_stream_chunks(
    reservation: LlamaAdmissionReservation,
    config: LlamaAdmissionConfig,
    *,
    request: Optional[Request],
    cancel_event,
):
    lease = reservation.lease_nowait()
    if lease is not None:
        yield lease
        return

    await _raise_if_openai_admission_cancelled(
        reservation,
        request = request,
        cancel_event = cancel_event,
    )
    deadline = None if config.queue_timeout_s is None else time.monotonic() + config.queue_timeout_s
    keepalive_interval_s = max(0.001, config.keepalive_interval_s)
    # At once, not after a full interval: a caller must not wait one out to learn it queued.
    yield _OPENAI_ADMISSION_SSE_WAIT
    next_keepalive_at = time.monotonic() + keepalive_interval_s
    try:
        while True:
            await _raise_if_openai_admission_cancelled(
                reservation,
                request = request,
                cancel_event = cancel_event,
            )
            lease = reservation.lease_nowait()
            if lease is not None:
                yield _OPENAI_ADMISSION_SSE_DONE
                yield lease
                return

            now = time.monotonic()
            wait_s = min(_OPENAI_LLAMA_ADMISSION_POLL_S, max(next_keepalive_at - now, 0.001))
            if deadline is not None:
                remaining_s = deadline - now
                if remaining_s <= 0:
                    reservation.cancel()
                    raise _openai_admission_timeout_error(reservation)
                wait_s = min(wait_s, max(remaining_s, 0.001))
            try:
                lease = await reservation.wait(wait_s)
            except asyncio.TimeoutError:
                lease = None
            if lease is not None:
                yield _OPENAI_ADMISSION_SSE_DONE
                yield lease
                return
            await _raise_if_openai_admission_cancelled(
                reservation,
                request = request,
                cancel_event = cancel_event,
            )
            now = time.monotonic()
            if now >= next_keepalive_at:
                next_keepalive_at = now + keepalive_interval_s
                yield _OPENAI_ADMISSION_SSE_WAIT
    except asyncio.CancelledError:
        reservation.cancel()
        raise


async def _close_openai_admitted_stream_iterator(iterator, *, cancelled: bool) -> None:
    if iterator is None:
        return
    if cancelled:
        athrow = getattr(iterator, "athrow", None)
        if athrow is not None:
            try:
                await athrow(asyncio.CancelledError())
            except (asyncio.CancelledError, StopAsyncIteration, RuntimeError):
                return
    aclose = getattr(iterator, "aclose", None)
    if aclose is not None:
        await aclose()


def _openai_compat_stream_stall_timeout():
    """Max silent gap after an OpenAI passthrough stream has produced data.

    If the socket goes silent after valid SSE data, this bounds how long the
    client is kept open. Defaults to the backend-wide stall timeout so this
    path stalls out like every sibling stream; set the env var to tighten it
    for local serving, or to 0 to disable the guard.
    """
    return _positive_float_env(
        _OPENAI_COMPAT_STREAM_STALL_TIMEOUT_ENV,
        _DEFAULT_STREAM_STALL_TIMEOUT_S,
    )


def _openai_passthrough_upstream_headers(*, llama_backend = None) -> dict:
    headers = {}
    auth_headers = getattr(llama_backend, "_auth_headers", None)
    if isinstance(auth_headers, dict):
        headers.update(auth_headers)
    headers["Connection"] = "close"
    return headers


class _CompatSameTaskTimeout:
    """Same-task timeout fallback for Python versions before asyncio.timeout."""

    def __init__(self, timeout_s: float):
        self.timeout_s = timeout_s
        self._task = None
        self._handle = None
        self._timed_out = False
        self._cancelling = 0

    async def __aenter__(self):
        self._task = asyncio.current_task()
        if self._task is None:
            return self
        if hasattr(self._task, "cancelling"):
            self._cancelling = self._task.cancelling()
        loop = asyncio.get_running_loop()
        self._handle = loop.call_later(max(self.timeout_s, 0), self._cancel_task)
        return self

    async def __aexit__(self, exc_type, exc, tb):
        if self._handle is not None:
            self._handle.cancel()
        if exc_type is not None and issubclass(exc_type, asyncio.CancelledError):
            if self._timed_out:
                if self._task is not None and hasattr(self._task, "uncancel"):
                    if self._task.uncancel() > self._cancelling:
                        return None
                raise asyncio.TimeoutError from exc
        return None

    def _cancel_task(self) -> None:
        self._timed_out = True
        if self._task is not None:
            self._task.cancel()


def _same_task_timeout(timeout_s: float):
    timeout_ctx = getattr(asyncio, "timeout", None)
    if timeout_ctx is not None:
        return timeout_ctx(timeout_s)
    return _CompatSameTaskTimeout(timeout_s)


class _SameTaskStreamingResponse(StreamingResponse):
    """StreamingResponse without Starlette's legacy AnyIO task-group wrapper."""

    def __init__(
        self,
        *args,
        unstarted_cleanup = None,
        **kwargs,
    ) -> None:
        super().__init__(*args, **kwargs)
        # Released when the client disconnects before the body iterator starts:
        # its try/finally never runs, so a stream that opens resources before the
        # first yield (the passthrough's upstream httpx stream) passes this.
        self._unstarted_cleanup = unstarted_cleanup

    async def __call__(self, scope, receive, send) -> None:
        # send() emits a body message only after the first chunk, so no body
        # message means the generator never entered its try/finally.
        body_started = False

        async def _tracking_send(message) -> None:
            nonlocal body_started
            if message.get("type") == "http.response.body":
                body_started = True
            await send(message)

        try:
            await self.stream_response(_tracking_send)
        except OSError:  # client disconnected mid-send
            if body_started:
                # Generator is suspended in its try/finally: throw CancelledError
                # (not aclose's GeneratorExit) so its handler finishes the
                # api_monitor entry. Fall back to aclose() without athrow.
                athrow = getattr(self.body_iterator, "athrow", None)
                if athrow is not None:
                    try:
                        await athrow(asyncio.CancelledError())
                    except (asyncio.CancelledError, StopAsyncIteration, RuntimeError):
                        pass
                else:
                    aclose = getattr(self.body_iterator, "aclose", None)
                    if aclose is not None:
                        await aclose()
            else:
                # Generator never started; aclose()/athrow() are no-ops on it, so
                # release eager resources via the hook. getattr guards a response
                # built through __new__ without __init__ (tests, pickling).
                aclose = getattr(self.body_iterator, "aclose", None)
                if aclose is not None:
                    await aclose()
                cleanup = getattr(self, "_unstarted_cleanup", None)
                if cleanup is not None:
                    try:
                        await cleanup()
                    except Exception:
                        pass
            raise ClientDisconnect()
        if self.background is not None:
            await self.background()


async def _release_unstarted_anthropic_stream(iterator, prior_cleanup) -> None:
    """Close a stream whose body never started, running the response's own
    pre-start hook. aclose() on an unstarted async generator is a no-op, so its
    finally never runs and anything the builder acquired eagerly (the passthrough
    cancel tracker) would leak without the hook."""
    aclose = getattr(iterator, "aclose", None)
    if aclose is not None:
        try:
            await aclose()
        except Exception:
            pass
    if prior_cleanup is not None:
        try:
            await prior_cleanup()
        except Exception:
            pass


def _tracked_cancel_unstarted_cleanup(tracker):
    """unstarted_cleanup that exits ``tracker`` on a pre-start disconnect, when
    the generator's finally (which normally exits it) never runs."""

    async def _cleanup() -> None:
        tracker.__exit__(None, None, None)

    return _cleanup


# Cloudflare quick tunnels (--secure) drop a request whose origin has sent no body
# bytes for ~100s, and a 600 GB GGUF load runs 100-330s. Measured on a real quick
# tunnel: headers at t=0 with no body still 524s, one space every 20s survives. So
# a slow call commits a 200 and pads until its payload is ready; leading whitespace
# is legal JSON, so clients parse the body as-is.
_TUNNEL_KEEPALIVE_AFTER_S = 15.0
_TUNNEL_KEEPALIVE_EVERY_S = 20.0

# Underscored so it cannot collide with a real field or the OpenAI ``error`` envelope.
_DEFERRED_ERROR_KEY = "_deferred_error"


def _deferred_error_body(status_code: int, detail) -> bytes:
    body = {_DEFERRED_ERROR_KEY: {"status_code": status_code, "detail": detail}}
    return json.dumps(body).encode()


async def _tunnel_safe_json(coro, *, label: str):
    """Await ``coro``, padding the response body if it outruns the tunnel timer.

    A call finishing within ``_TUNNEL_KEEPALIVE_AFTER_S`` keeps the current
    contract exactly, HTTPException status code included; every early failure
    (validation, unknown identifier, download-manager and sidecar 409s) raises in
    that window. Only a slower call switches to a padded stream, and it must
    report a late failure in the body because the status line is already gone.

    A client disconnect does not cancel the work: the model stays resident, as
    it does today.
    """
    task = asyncio.ensure_future(coro)
    # A client that disconnects mid-pad leaves nobody to await the task, and an
    # unretrieved exception logs "Task exception was never retrieved". Retrieving
    # it here does not consume it: result() below still raises.
    task.add_done_callback(lambda t: t.cancelled() or t.exception())
    done, _ = await asyncio.wait({task}, timeout = _TUNNEL_KEEPALIVE_AFTER_S)
    if done:
        return task.result()  # re-raises exactly as an un-wrapped await would

    logger.info(
        f"{label} exceeded {_TUNNEL_KEEPALIVE_AFTER_S:.0f}s; "
        "padding the response so a proxy cannot time it out"
    )

    async def _body():
        while True:
            finished, _ = await asyncio.wait({task}, timeout = _TUNNEL_KEEPALIVE_EVERY_S)
            if not finished:
                yield b" "
                continue
            try:
                payload = task.result()
            except HTTPException as exc:
                logger.info(f"{label} failed with {exc.status_code} after the response committed")
                yield _deferred_error_body(exc.status_code, exc.detail)
            except Exception as exc:
                logger.exception(f"{label} failed after the response was committed")
                yield _deferred_error_body(500, f"{type(exc).__name__}: {exc}")
            else:
                yield json.dumps(jsonable_encoder(payload)).encode()
            return

    return _SameTaskStreamingResponse(
        _body(),
        media_type = "application/json",
        headers = {"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
    )


async def _aclose_stream_resources(
    *,
    watchers = (),
    iterator = None,
    resp = None,
    client = None,
) -> None:
    """Tear down an httpx streaming generator's resources in the required order:
    cancel + bounded-wait each watcher task, then aclose() the byte/line iterator,
    the response, and the client. Each step swallows its own exceptions so teardown
    always completes; a close-time CancelledError is re-raised only after every
    step has run. See _anthropic_passthrough_stream for the ordering rationale."""
    # Bounded: a watcher parked in Request.is_disconnected() can swallow cancel(), so an
    # unbounded await holds the response open. Stopped together, so N watchers cost one
    # bound before the closes, which are what stop llama-server decoding. #7617
    live = [w for w in watchers if w is not None]
    if live:
        # Cancel before the first await, else a cancel here stops the gather before it
        # steps its children, leaving watchers never cancelled.
        for watcher in live:
            watcher.cancel()
        try:
            await asyncio.gather(
                *(_stop_local_disconnect_cancel_watcher(w) for w in live),
                return_exceptions = True,
            )
        except (asyncio.CancelledError, Exception):
            pass
    close_cancelled = False
    if iterator is not None:
        try:
            await iterator.aclose()
        except asyncio.CancelledError:
            close_cancelled = True
        except Exception:
            pass
    if resp is not None:
        try:
            await resp.aclose()
        except asyncio.CancelledError:
            close_cancelled = True
        except Exception:
            pass
    if client is not None:
        try:
            await client.aclose()
        except asyncio.CancelledError:
            close_cancelled = True
        except Exception:
            pass
    if close_cancelled:
        raise asyncio.CancelledError()


# The loop holds only weak refs to tasks, so a bare ensure_future() close can be collected
# before it runs. Strong ref until done.
_LATE_CLOSE_TASKS: set = set()


async def _aclose_quietly(obj) -> None:
    try:
        await obj.aclose()
    except Exception:
        pass


def _discard_task_outcome(task: asyncio.Task) -> None:
    """Drain an abandoned teardown task, closing a late response rather than dropping it.

    Closing the per-request client does not close a response the send produces on a
    connection opened after that close. Never raises: this is a done callback. #7617
    """
    try:
        if task.cancelled():
            return
        if task.exception() is not None:
            return
        result = task.result()
    except Exception:
        return
    if result is not None and hasattr(result, "aclose") and not getattr(result, "is_closed", False):
        try:
            closing = asyncio.ensure_future(_aclose_quietly(result))
        except RuntimeError:
            return
        _LATE_CLOSE_TASKS.add(closing)
        closing.add_done_callback(_LATE_CLOSE_TASKS.discard)


def _release_admission(admission_lease = None, tracker = None) -> None:
    """Give back the process-wide llama-server slot and the cancel-registry entry.

    Must run after the upstream response is closed: on disconnect llama-server keeps
    decoding until ``resp`` is closed, so releasing first admits a second request past
    --parallel. Safe behind the closes only because every teardown await is bounded. #7617
    """
    try:
        if admission_lease is not None:
            admission_lease.release()
    finally:
        if tracker is not None:
            tracker.__exit__(None, None, None)


async def _preheader_cancelled(cancel_event = None, request: Optional[Request] = None) -> bool:
    if cancel_event is not None and cancel_event.is_set():
        return True
    if request is not None and await request.is_disconnected():
        if cancel_event is not None:
            cancel_event.set()
        return True
    return False


def _mark_cancelled_json_response_failed(request: Request, cancel_event: threading.Event) -> None:
    """Keep a partial JSON response from claiming a preview-owned resident model."""
    if cancel_event.is_set():
        from core.inference.llama_keepwarm import mark_response_failed
        mark_response_failed(getattr(request, "scope", None))


async def _wait_preheader_cancel(cancel_event = None, request: Optional[Request] = None) -> None:
    while not await _preheader_cancelled(cancel_event, request):
        await asyncio.sleep(0.05)


async def _send_stream_with_preheader_cancel(
    client: httpx.AsyncClient,
    req: httpx.Request,
    cancel_event = None,
    request: Optional[Request] = None,
    mark_cancel_on_cancel: bool = True,
) -> Optional[httpx.Response]:
    if cancel_event is None and request is None:
        return await client.send(req, stream = True)
    from core.inference.llama_keepwarm import mark_response_failed

    def _mark_preheader_cancel() -> None:
        # Cancelled before the upstream response started: the caller ends its 200
        # stream without serving tokens, so flag it failed or the middleware claims
        # a preview-owned slot for a request that never used the model.
        mark_response_failed(getattr(request, "scope", None))

    if await _preheader_cancelled(cancel_event, request):
        _mark_preheader_cancel()
        return None

    send_task = asyncio.create_task(client.send(req, stream = True))
    cancel_task = asyncio.create_task(_wait_preheader_cancel(cancel_event, request))

    async def _stop_send_task() -> None:
        try:
            await client.aclose()
        except Exception:
            pass
        # Bounded: the client is already closed, so an abandoned send owns nothing and
        # the callback drains its result. #7617
        send_task.cancel()
        done, _pending = await asyncio.wait({send_task}, timeout = _TEARDOWN_TASK_STOP_TIMEOUT_S)
        if not done:
            send_task.add_done_callback(_discard_task_outcome)
            return
        try:
            # The aclose() above does not close a response the send produced during it.
            sent = send_task.result()
            if sent is not None:
                await _aclose_quietly(sent)
        except (asyncio.CancelledError, Exception):
            pass

    try:
        done, _pending = await asyncio.wait(
            {send_task, cancel_task},
            return_when = asyncio.FIRST_COMPLETED,
        )
        if send_task in done:
            return await send_task

        await _stop_send_task()
        _mark_preheader_cancel()
        return None
    except asyncio.CancelledError:
        if mark_cancel_on_cancel and cancel_event is not None:
            cancel_event.set()
        await _stop_send_task()
        raise
    finally:
        # Bounded: cancel_task polls Request.is_disconnected(), which can swallow cancel(),
        # and this finally also runs on the success path, before the first byte. #7617
        try:
            await _stop_local_disconnect_cancel_watcher(cancel_task)
        except (asyncio.CancelledError, Exception):
            pass


async def _aiter_llama_stream_items(
    async_iter,
    *,
    cancel_event = None,
    request: Optional[Request] = None,
    first_token_deadline: Optional[float] = None,
    response: Optional[httpx.Response] = None,
    post_first_item_read_timeout_s: Optional[
        Union[float, Callable[[], Optional[float]]]
    ] = _DEFAULT_STREAM_STALL_TIMEOUT_S,
):
    if first_token_deadline is None:
        first_token_deadline = time.monotonic() + _DEFAULT_FIRST_TOKEN_TIMEOUT_S
    last_item_at: Optional[float] = None

    def _post_first_timeout_s() -> Optional[float]:
        if callable(post_first_item_read_timeout_s):
            return post_first_item_read_timeout_s()
        return post_first_item_read_timeout_s

    while True:
        if cancel_event is not None and cancel_event.is_set():
            return
        if request is not None and await request.is_disconnected():
            if cancel_event is not None:
                cancel_event.set()
            return
        waiting_first_item = last_item_at is None
        try:
            if waiting_first_item:
                remaining_s = first_token_deadline - time.monotonic()
                if remaining_s <= 0:
                    raise httpx.ReadTimeout("The model did not produce a first token in time.")
                if response is not None:
                    _set_stream_response_read_timeout(response, remaining_s)
                # Keep httpx/httpcore's AnyIO cancel scope in this task.
                # asyncio.wait_for would drive __anext__ in a child task.
                async with _same_task_timeout(remaining_s):
                    item = await async_iter.__anext__()
            else:
                timeout_s = _post_first_timeout_s()
                if (
                    request is not None
                    and response is not None
                    and timeout_s is not None
                    and last_item_at is not None
                ):
                    stall_remaining_s = timeout_s - (time.monotonic() - last_item_at)
                    if stall_remaining_s <= 0:
                        raise httpx.ReadTimeout("The model stopped producing tokens mid-response.")
                    _set_stream_response_read_timeout(response, stall_remaining_s)
                item = await async_iter.__anext__()
        except asyncio.TimeoutError as exc:
            if waiting_first_item:
                raise httpx.ReadTimeout("The model did not produce a first token in time.") from exc
            raise
        except StopAsyncIteration:
            return
        except httpx.ReadTimeout:
            now = time.monotonic()
            if last_item_at is None:
                if now >= first_token_deadline:
                    raise
                continue
            timeout_s = _post_first_timeout_s()
            if request is not None and timeout_s is not None and now - last_item_at < timeout_s:
                continue
            raise httpx.ReadTimeout("The model stopped producing tokens mid-response.")
        if last_item_at is None and response is not None:
            # The first-token read deadline no longer applies once a chunk has
            # arrived: switch to the stall timeout, or clear the read timeout
            # entirely when the stall guard is disabled (callable returns None)
            # so a long gap can't trip the stale first-token deadline.
            _set_stream_response_read_timeout(response, _post_first_timeout_s())
        last_item_at = time.monotonic()
        yield item


